"""Generate the Unicode 15.1 tables that the ISBN normalization protocol depends on, and check the committed copies.

Why: data-model 7.1 pins NFKC to Unicode 15.1. A runtime with a newer Unicode database adds compatibility decompositions
(for example Unicode 16.0's OUTLINED DIGIT), so the protocol first splits the input at code points that are not assigned
in 15.1 and applies NFKC only to the assigned runs. The assigned ranges come from DerivedAge-15.1.0.txt and are written as
the same table for C# (Application/Catalog) and Python (crawler/catalog_core). NormalizationTest.txt is trimmed to the
two columns the C# conformance test needs (c1 source, c4 NFKC).

Usage: unicode_tables.py --check   (default; fails when a committed file differs from the vendored data)
       unicode_tables.py --write   (regenerates the committed files)
"""

import argparse
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
FIXTURE_DIR = Path("tests/Fixtures/unicode-15.1")
DERIVED_AGE = "DerivedAge.txt"
NORMALIZATION_TEST = "NormalizationTest.txt"
NFKC_TRIMMED = "NormalizationTest-NFKC.txt"
CS_TABLE = Path("Application/Catalog/Unicode151Assigned.cs")
PY_TABLE = Path("crawler/catalog_core/unicode_15_1.py")
EXPECTED_VERSION = (15, 1)
NOTICE_HEADER = [
    "# Trimmed by .github/scripts/unicode_tables.py from NormalizationTest.txt (Unicode 15.1.0).",
    "# Columns kept: c1 (source) and c4 (NFKC). Other columns are not used by the protocol.",
]


def _version(text: str) -> tuple[int, int]:
    major, _, minor = text.strip().partition(".")
    return int(major), int(minor or 0)


def parse_assigned_ranges(derived_age_text: str) -> list[tuple[int, int]]:
    """Return sorted, merged inclusive ranges of code points that have an age (assigned) in Unicode 15.1."""
    first_line = derived_age_text.splitlines()[0]
    if "DerivedAge-15.1.0" not in first_line:
        raise ValueError(f"not the Unicode 15.1 DerivedAge file: {first_line!r}")

    ranges: list[tuple[int, int]] = []
    for raw in derived_age_text.splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        code_points, _, age = line.partition(";")
        if not age.strip():
            raise ValueError(f"missing age in line {raw!r}")
        if _version(age) > EXPECTED_VERSION:
            raise ValueError(f"age {age.strip()} is newer than Unicode 15.1 in line {raw!r}")
        start_text, _, end_text = code_points.strip().partition("..")
        start = int(start_text, 16)
        end = int(end_text, 16) if end_text else start
        ranges.append((start, end))

    ranges.sort()
    merged: list[tuple[int, int]] = []
    for start, end in ranges:
        if merged and start <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def trim_normalization_test(text: str) -> str:
    """Keep the Unicode license header and the c1;c4 pairs of NormalizationTest.txt."""
    header = [line for line in text.splitlines() if line.startswith("#")][:5]
    pairs = []
    for raw in text.splitlines():
        if not raw or raw.startswith(("#", "@")):
            continue
        columns = raw.split("#", 1)[0].split(";")
        if len(columns) < 5:
            raise ValueError(f"unexpected NormalizationTest line: {raw!r}")
        pairs.append(f"{columns[0].strip()};{columns[3].strip()}")
    return "\n".join([*header, *NOTICE_HEADER, *pairs]) + "\n"


def render_cs(ranges: list[tuple[int, int]]) -> str:
    flat = [value for pair in ranges for value in pair]
    rows = [flat[i : i + 8] for i in range(0, len(flat), 8)]
    body = "\n".join("        " + ", ".join(f"0x{value:04X}" for value in row) + "," for row in rows)
    return f"""// <auto-generated>
// Generated by .github/scripts/unicode_tables.py from tests/Fixtures/unicode-15.1/DerivedAge.txt. Do not edit by hand.
// </auto-generated>
namespace Book_Finder.Application.Catalog;

// Code points assigned in Unicode 15.1 (data-model 7.1). NFKC is applied only to runs of these code points, so the
// result does not depend on the runtime's Unicode version.
public static class Unicode151Assigned
{{
    // Flat, sorted, non-overlapping inclusive pairs: start0, end0, start1, end1, ...
    private static readonly int[] Bounds =
    [
{body}
    ];

    public static bool Contains(int codePoint)
    {{
        var low = 0;
        var high = Bounds.Length / 2 - 1;
        while (low <= high)
        {{
            var middle = (low + high) / 2;
            if (codePoint < Bounds[middle * 2])
                high = middle - 1;
            else if (codePoint > Bounds[middle * 2 + 1])
                low = middle + 1;
            else
                return true;
        }}

        return false;
    }}
}}
"""


def render_py(ranges: list[tuple[int, int]]) -> str:
    body = "\n".join(f"    (0x{start:04X}, 0x{end:04X})," for start, end in ranges)
    return f'''"""Code points assigned in Unicode 15.1.

Generated by .github/scripts/unicode_tables.py from tests/Fixtures/unicode-15.1/DerivedAge.txt. Do not edit by hand.
The ISBN normalization protocol (data-model 7.1) applies NFKC only to runs of these code points.
"""

from bisect import bisect_right

# Sorted, non-overlapping inclusive ranges (start, end).
ASSIGNED_RANGES: tuple[tuple[int, int], ...] = (
{body}
)

_STARTS = tuple(start for start, _ in ASSIGNED_RANGES)


def is_assigned(code_point: int) -> bool:
    index = bisect_right(_STARTS, code_point) - 1
    return index >= 0 and code_point <= ASSIGNED_RANGES[index][1]
'''


def build_outputs(fixture_dir: Path, root: Path) -> dict[Path, str]:
    """Return the expected content of every generated file, keyed by its path under root."""
    derived = (fixture_dir / DERIVED_AGE).read_text(encoding="utf-8")
    normalization = (fixture_dir / NORMALIZATION_TEST).read_text(encoding="utf-8")
    ranges = parse_assigned_ranges(derived)
    return {
        fixture_dir / NFKC_TRIMMED: trim_normalization_test(normalization),
        root / CS_TABLE: render_cs(ranges),
        root / PY_TABLE: render_py(ranges),
    }


def main(argv: list[str] | None = None, root: Path = REPO) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="fail when a committed file differs (default)")
    mode.add_argument("--write", action="store_true", help="regenerate the committed files")
    args = parser.parse_args(argv)

    fixture_dir = root / FIXTURE_DIR
    outputs = build_outputs(fixture_dir, root)
    drift = []
    for path, expected in outputs.items():
        if args.write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8", newline="\n")
        elif not path.is_file() or path.read_text(encoding="utf-8") != expected:
            drift.append(path)

    if args.write:
        print(f"wrote {len(outputs)} file(s)")
        return 0
    for path in drift:
        print(f"::error::{path.relative_to(root)} differs from the Unicode 15.1 data; run .github/scripts/unicode_tables.py --write")
    if drift:
        return 1
    print(f"unicode tables OK ({len(outputs)} file(s))")
    return 0


if __name__ == "__main__":
    sys.exit(main())
